<template><div><PageHeader eyebrow="Product Configuration" title="套餐管理" description="维护当前发布套餐的价格、周期、成员上限和上下架状态。"><button class="layui-btn monitor-primary" @click="$router.push('/plans/new/edit')">新建套餐</button></PageHeader><div v-if="loading" class="panel loading-state">正在加载套餐…</div><section v-else class="plan-grid"><article v-for="plan in plans" :key="plan.id" class="panel plan-card"><header><div><span :class="['tag',plan.status?'success':'muted']">{{plan.status?'已上架':'已下架'}}</span><h2>{{plan.name}}</h2><p>{{plan.description}}</p></div><span class="plan-code">{{plan.code}}</span></header><div class="price"><strong>¥ {{format(plan.price)}}</strong><span>/ {{period(plan.billingCycle)}}</span></div><ul><li>最多 {{plan.memberLimit}} 名企业成员</li><li>套餐时长 {{plan.durationDays}} 天</li><li>展示排序 {{plan.sortOrder}}</li></ul><footer><router-link class="layui-btn monitor-secondary" :to="`/plans/${plan.id}/edit`">编辑套餐</router-link><button class="layui-btn" :class="plan.status?'monitor-danger':'monitor-primary'" @click="openStatus(plan)">{{plan.status?'下架':'上架'}}</button></footer></article></section><section class="panel change-note"><i class="layui-icon layui-icon-tips"></i><div><strong>套餐变更说明</strong><p>修改套餐不会影响已生成订单，历史价格和权益由订单快照保留。</p></div></section><AppModal v-model="statusModal" :title="targetPlan?.status?'下架套餐':'上架套餐'" :confirm-text="targetPlan?.status?'确认下架':'确认上架'" :danger="Boolean(targetPlan?.status)" :loading="submitting" @confirm="changeStatus"><p>将{{targetPlan?.status?'下架':'上架'}}“{{targetPlan?.name}}”。已有订阅不会被终止。</p><div class="field"><label>操作原因 *</label><textarea v-model.trim="reason" class="layui-textarea"></textarea><p v-if="formError" class="error-text">{{formError}}</p></div></AppModal><AppToast :message="toastMessage" :type="toastType" /></div></template>
<script>import PageHeader from '@/components/PageHeader.vue';import AppModal from '@/components/AppModal.vue';import AppToast from '@/components/AppToast.vue';import feedback from '@/mixins/feedback';import { planApi } from '@/api/monitor';export default{name:'PlanListPage',components:{PageHeader,AppModal,AppToast},mixins:[feedback],data:()=>({plans:[],loading:true,statusModal:false,targetPlan:null,reason:'',formError:'',submitting:false}),mounted(){this.load();},methods:{format:v=>Number(v||0).toLocaleString('zh-CN'),period:v=>({YEAR:'年',MONTH:'月',DAY:'期'}[v]||v),async load(){this.loading=true;try{this.plans=await planApi.list();}catch(e){this.errorMessage(e);}finally{this.loading=false;}},openStatus(plan){this.targetPlan=plan;this.reason='';this.formError='';this.statusModal=true;},async changeStatus(){if(!this.reason){this.formError='请填写操作原因';return;}this.submitting=true;try{await planApi.updateStatus(this.targetPlan.id,{status:this.targetPlan.status?0:1,reason:this.reason});this.statusModal=false;await this.load();this.notify('套餐状态已更新');}catch(e){this.errorMessage(e);}finally{this.submitting=false;}}}};</script><style scoped>.plan-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.plan-card{padding:20px}.plan-card header{display:flex;justify-content:space-between;gap:12px}.plan-card h2{margin:14px 0 4px;font-size:20px}.plan-card p{margin:0;color:var(--muted)}.plan-code{color:var(--muted);font-size:12px}.price{margin:22px 0;padding:16px 0;border-block:1px solid var(--border)}.price strong{font-size:26px}.price span{color:var(--muted)}.plan-card ul{min-height:116px;margin:0;padding-left:18px}.plan-card li{margin:10px 0}.plan-card footer{display:flex;gap:8px}.plan-card footer>*{flex:1}.change-note{display:flex;gap:12px;margin-top:16px;padding:18px}.change-note>i{color:var(--primary);font-size:24px}.change-note p{margin:3px 0 0;color:var(--muted)}@media(max-width:1200px){.plan-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.plan-grid{grid-template-columns:1fr}}</style>
